      ,
      "why": "Only family with a feasible Pareto point; explore lower area by reducing W, increasing m, and using the accuracy margin."
      },
      {
        "family": "pipelined",
        "ranges": [
          {"param": "data_width", "low": 25, "high": 28, "choices": null},
          {"param": "n_iter", "low": 25, "high": 30, "choices": null},
